def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 99:
        return 'D'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_C = sum(1 for x in opp if x == 'C')
    opp_D = n - opp_C
    my_D = sum(1 for x in my if x == 'D')
    last_opp = opp[-1]
    last_me = my[-1]

    # If opponent has never defected, exploit up to their typical forgiveness threshold.
    if opp_D == 0:
        if last_me == 'D':
            return 'C'
        if my_D < n // 10:
            return 'D'
        return 'C'

    # Opponent has defected at least once.
    if last_opp == 'D':
        # Forgive if we recently defected, or if opponent's defection count is still low.
        if last_me == 'D' or (n >= 2 and my[-2] == 'D'):
            return 'C'
        if opp_D <= max(1, n // 10):
            return 'C'
        # Otherwise retaliate with some probability.
        if rng.random() < 0.7:
            return 'D'
        return 'C'
    else:
        # Opponent cooperated: cooperate to maintain mutual cooperation.
        return 'C'
